class QueryJoinOptimizerUnionExtensionPriorityTest {

	private static final Value BRANCH_VALUE = SimpleValueFactory.getInstance().createIRI("urn:branch");
	private static final Value SIBLING_VALUE = SimpleValueFactory.getInstance().createIRI("urn:sibling");

	@Test
	void unscopedUnionMustNotOverwriteAReorderedSiblingsBinding() {
		QueryRoot original = unionBeforeValues(new ValueConstant(BRANCH_VALUE));
		QueryRoot optimized = original.clone();

		// Each branch binds x to an incompatible value, so the original join has no solutions. Moving VALUES
		// ahead of the UNION would let each BIND overwrite its x and incorrectly produce two solutions.
		assertThat(evaluate(original)).isEmpty();

		new QueryJoinOptimizer(new PreferValuesStatistics()).optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(evaluate(optimized)).isEmpty();
	}

	@Test
	void failedUnionAssignmentMustNotRemoveAReorderedSiblingsBinding() {
		QueryRoot original = unionBeforeValues(Var.of("missing"));
		QueryRoot optimized = original.clone();
		BindingSet expected = new ListBindingSet(List.of("x"), SIBLING_VALUE);

		// A failed branch-local BIND leaves x available for the later VALUES. Reversing the operands would
		// instead remove the already supplied x. Preserve both duplicate rows and their binding domains.
		assertThat(evaluate(original)).containsExactlyInAnyOrder(expected, expected);

		new QueryJoinOptimizer(new PreferValuesStatistics()).optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(evaluate(optimized)).containsExactlyInAnyOrder(expected, expected);
	}

	@Test
	void unionWrapperMustNotTurnANullableFilterReadIntoAnInheritedBinding() {
		Extension branch = new Extension(values("x", EmptyBindingSet.getInstance()),
				new ExtensionElem(new ValueConstant(BRANCH_VALUE), "label"));
		Union union = new Union(branch, branch.clone());
		union.setVariableScopeChange(true);
		Filter filter = new Filter(union, new Bound(Var.of("x")));
		filter.setVariableScopeChange(true);
		BindingSetAssignment supplier = values("x", new ListBindingSet(List.of("x"), SIBLING_VALUE));
		BindingSetAssignment tail = values("z", new ListBindingSet(List.of("z"), SIBLING_VALUE));
		QueryRoot original = new QueryRoot(new Join(filter, new Join(supplier, tail)));
		QueryRoot optimized = original.clone();

		// The UNION declares x but never supplies it. BOUND therefore rejects both source rows. If this
		// wrapper ceased being a priority operand, a cheap supplier could precede it in Join(supplier,
		// Join(filter, tail)); the inner join's entry binding would then make BOUND succeed despite both markers.
		assertThat(evaluate(original)).isEmpty();

		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression instanceof Filter) {
					return 100.0d;
				}
				if (expression instanceof BindingSetAssignment assignment
						&& assignment.getBindingNames().contains("z")) {
					return 1_000.0d;
				}
				return super.getCardinality(expression);
			}
		};
		new QueryJoinOptimizer(statistics).optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(evaluate(optimized)).isEmpty();
	}

	@Test
	void unionBindMustPreserveImplicitValuesCorrelationInNestedSlice() {
		BindingSetAssignment existsValues = values("x", new ListBindingSet(List.of("x"), BRANCH_VALUE));
		Extension branch = new Extension(new SingletonSet(),
				new ExtensionElem(new Exists(new Slice(existsValues, 0, 1)), "seen"));
		Union union = new Union(branch, branch.clone());
		union.setVariableScopeChange(true);
		BindingSetAssignment supplier = values("x", new ListBindingSet(List.of("x"), SIBLING_VALUE));
		BindingSetAssignment tail = values("z", new ListBindingSet(List.of("z"), SIBLING_VALUE));
		QueryRoot original = new QueryRoot(new Join(union, new Join(supplier, tail)));
		QueryRoot optimized = original.clone();
		BindingSet expected = new ListBindingSet(List.of("x", "seen", "z"), SIBLING_VALUE,
				SimpleValueFactory.getInstance().createLiteral(true), SIBLING_VALUE);

		// VALUES reads its declared x through the EXISTS input, although the expression has no Var(x) node.
		// A modifier inside a value subquery does not classify the enclosing tuple join as independent.
		assertThat(evaluate(original)).containsExactlyInAnyOrder(expected, expected);
		QueryRoot reordered = new QueryRoot(new Join(supplier.clone(), new Join(tail.clone(), union.clone())));
		BindingSet incorrectlyCorrelated = new ListBindingSet(List.of("x", "seen", "z"), SIBLING_VALUE,
				SimpleValueFactory.getInstance().createLiteral(false), SIBLING_VALUE);
		assertThat(evaluate(reordered)).containsExactlyInAnyOrder(incorrectlyCorrelated, incorrectlyCorrelated);

		new QueryJoinOptimizer(new PreferValuesStatistics()).optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(evaluate(optimized)).containsExactlyInAnyOrder(expected, expected);
	}

	private static QueryRoot unionBeforeValues(ValueExpr expression) {
		Union union = new Union(
				new Extension(new SingletonSet(), new ExtensionElem(expression, "x")),
				new Extension(new SingletonSet(), new ExtensionElem(expression.clone(), "x")));
		// Programmatically built unscoped algebra has not necessarily passed the UNION scope-removal proof.
		union.setVariableScopeChange(false);
		BindingSetAssignment values = values("x", new ListBindingSet(List.of("x"), SIBLING_VALUE));
		return new QueryRoot(new Join(union, values));
	}

	private static BindingSetAssignment values(String name, BindingSet... rows) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of(name));
		values.setBindingSets(List.of(rows));
		return values;
	}

	private static List<BindingSet> evaluate(TupleExpr expression) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> rows = new ArrayList<>();
		// Evaluation annotates algorithms, so keep those annotations out of the optimizer's input tree.
		try (CloseableIteration<BindingSet> results = strategy.evaluate(expression.clone(),
				EmptyBindingSet.getInstance())) {
			while (results.hasNext()) {
				rows.add(new QueryBindingSet(results.next()));
			}
		}
		return rows;
	}

	private static final class PreferValuesStatistics extends EvaluationStatistics {
		@Override
		public double getCardinality(TupleExpr expression) {
			return expression instanceof Union ? 1_000.0d : super.getCardinality(expression);
		}
	}
}
